const k = $input.first().json;
const system = "You are an environmental data analyst supporting the Maharashtra Pollution Control Board. Use ONLY the numbers provided. Never invent figures. Present causes as 'possible causes', not facts. Write in plain English for regulators and public health officials. Be concise.";
const prompt = `Daily water quality KPIs for Maharashtra (MPCB monitoring network), date ${k.sampling_date}:
- Total samples analysed: ${k.total_samples}
- Non-compliant samples (against designated class): ${k.pct_non_compliant}%
- Average BOD: ${k.avg_bod} mg/L (safe limit about 3 mg/L)
- Average dissolved oxygen: ${k.avg_do} mg/L (minimum about 5 mg/L)
- Stations rated High risk: ${k.high_risk_stations}
- Stations with dissolved oxygen below 5 mg/L: ${k.low_do_stations}
- Fecal coliform exceedances (>500 MPN/100mL): ${k.fecal_coliform_exceedances}
- District with most high-risk stations: ${k.district_highest_risk}

Write a daily environmental summary of at most 110 words:
1) one sentence on overall status, 2) the two most important concerns with the numbers, 3) one recommended regulatory action. Do not add facts that are not above.`;
return [{ json: { system, prompt } }];

const t = ($input.first().json.content || []).filter(b => b.type === 'text').map(b => b.text).join('
');
return [{ json: { message: 'Daily Water Quality Summary

' + t } }];
